7	die() {
8	    printf '%s: %s\n' "$(basename "$0")" "$*" >&2
9	    exit 64
10	}
11	
12	now_epoch() {
13	    if [[ -n "${BEACON_NOW:-}" ]]; then
14	        date -u -d "${BEACON_NOW}" +%s
15	    else
16	        date -u +%s
17	    fi
18	}
19	
20	iso_to_epoch() {
21	    date -u -d "$1" +%s 2>/dev/null || die "bad timestamp: $1"
22	}
23	
24	require_status() {
25	    [[ -r "$1" ]] || die "cannot read status file: $1"
26	}
27	
28	read_status() {
29	    local file="$1"
30	    grep -v -e '^[[:space:]]*#' -e '^[[:space:]]*$' "${file}"
31	}
